SELECT

FROM log_business_change


    AND operator_id = #{operatorId,jdbcType=VARCHAR}


    AND token = #{token,jdbcType=VARCHAR}


    AND business_institute_id = #{businessInstituteId,jdbcType=VARCHAR}


    AND business_type = #{businessType,jdbcType=CHAR}


    AND business_id = #{businessId,jdbcType=VARCHAR}


    AND operation_type = #{operationType,jdbcType=CHAR}


    AND operation_time BETWEEN #{operationTimeStart,jdbcType=TIMESTAMP} AND #{operationTimeEnd,jdbcType=TIMESTAMP}
